head.script:
scwin.screenId = "jldfil59411";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 15
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        await scwin.checkSave();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil59411.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)
/**
 * @method
 * @name scwin.init_sessionFill
 * @author Inswave
 * @date 2026. 09. 15
 * @param
 * @returns
 * @hidden N
*/
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil59411' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — jldfil59411: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 15
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { $c.data.recvParamData('dma_pageContext'); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 15
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_sessionFill();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil59411.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_saveAdjReq_onclick
 * @author Inswave
 * @date 2026. 09. 15
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_saveAdjReq_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.saveAdjReq()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil59411.btn_saveAdjReq_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.saveAdjReq
 * @author Inswave
 * @date 2026. 09. 15
 * @param
 * @returns
 * @hidden N
*/
scwin.saveAdjReq = async function () {
    const msg = "수정 승인 후 다시 접수 될때까지 같은 업무에 대해서 수정요청 할 수 없습니다. \r\n수정요청 하시겠습니까?";
    if (await scwin.checkValue()) {
        if (await $c.win.confirm(msg)) {
            $("#ListInvstgAdjReqForm").submit();
        }
    }
};


/**
 * @method
 * @name scwin.checkSave
 * @author Inswave
 * @date 2026. 09. 15
 * @param
 * @returns
 * @hidden N
*/
scwin.checkSave = async function () {
    const isOk = (String(($c.data.readValue("dma_pageContext", "isOk", { ctx: true, soft: true, label: "isOk" })) == null ? '' : ($c.data.readValue("dma_pageContext", "isOk", { ctx: true, soft: true, label: "isOk" }))).indexOf('$' + '{') >= 0 ? '' : String(($c.data.readValue("dma_pageContext", "isOk", { ctx: true, soft: true, label: "isOk" })) == null ? '' : ($c.data.readValue("dma_pageContext", "isOk", { ctx: true, soft: true, label: "isOk" }))));
    if (isOk !== '') {
        if (isOk === 'Y') {
            await $c.win.alert('수정요청 되었습니다.');
        } else {
            await $c.win.alert('수정요청 중 오류가 발생 되었습니다.');
        }
        $c.win.setPageFrameSrc(null,null);
        $c.win.closePopup();
    }
};


/**
 * @method
 * @name scwin.checkValue
 * @author Inswave
 * @date 2026. 09. 15
 * @param
 * @returns
 * @hidden N
*/
scwin.checkValue = async function () {
    if ($c.util.getComponent('txa_chgRsn').getValue().length === 0) {
        await $c.win.alert('수정 사유를 입력 하세요.');
        return false;
    }
    if ($c.data.readValue('dma_hiddenStore', 'slc_listBzDtlTpCd', { silent: true }) === "") {
        await $c.win.alert('수정 요청 업무를 선택 하세요.');
        return false;
    }
    return true;
};
